(2579076, 356232, 40019, '<td valign="top">Cool image!  Great sharpness and nice combination of shapes and textures. Great lighting.  Good luck!</td>', 'Cool image!  Great sharpness and nice combination of shapes and textures. Great lighting.  Good luck!', '2006-07-03 13:31:17.000000', NULL, 1),
(2579086, 356594, 318, '<td valign="top">Too bad that you couldn''t get closer.</td>', 'Too bad that you couldn''t get closer.', '2006-07-03 13:32:47.000000', NULL, 1),
