(2579121, 357337, 57519, '<td valign="top">Would be rated higher if you had better focus. Looks like a real nice place.</td>', 'Would be rated higher if you had better focus. Looks like a real nice place.', '2006-07-03 13:44:25.000000', NULL, 1),
(2579146, 356894, 57519, '<td valign="top">At first I was thinking you have a trembling disorder. But the more you look at this picture, the more you want to hang it on the wall. Seriously! You made a great abstract.</td>', 'At first I was thinking you have a trembling disorder. But the more you look at this picture, the more you want to hang it on the wall. Seriously! You made a great abstract.', '2006-07-03 13:51:16.000000', NULL, 1),
