(2579190, 356030, 45250, '<td valign="top">Dang man....put your arm around that pretty lady!!!</td>', 'Dang man....put your arm around that pretty lady!!!', '2006-07-03 14:06:18.000000', NULL, 1),
(2579193, 357309, 7322, '<td valign="top">I like the composition---the way the frame is divided diagonally. It looks a bit overexposed to me. I''d like to see more detail in the texture of the concrete. The glare in the water is hurting this also.</td>', 'I like the composition---the way the frame is divided diagonally. It looks a bit overexposed to me. I''d like to see more detail in the texture of the concrete. The glare in the water is hurting this also.', '2006-07-03 14:07:37.000000', NULL, 1),
(2579202, 356522, 7322, '<td valign="top">I like the sharp focus on the eyelash and the simplicity of the composition. Although I think you had the right idea with this tight cropping of the frame, I''d like to see a bit more of the child''s face and less of the t-shirt.</td>', 'I like the sharp focus on the eyelash and the simplicity of the composition. Although I think you had the right idea with this tight cropping of the frame, I''d like to see a bit more of the child''s face and less of the t-shirt.', '2006-07-03 14:12:18.000000', NULL, 1),
(2579206, 356456, 31399, '<td valign="top">wonderfully tranquil and ''cool temp'' shot...lovely..very serene.  10+</td>', 'wonderfully tranquil and ''cool temp'' shot...lovely..very serene.  10+', '2006-07-03 14:12:59.000000', NULL, 1),
(2579209, 356669, 42125, '<td valign="top">Does she know?</td>', 'Does she know?', '2006-07-03 14:13:30.000000', NULL, 1),
(2579213, 356485, 7322, '<td valign="top">This is an interesting subject. The exposure could have been stopped down a bit. The highlights are blown out and the shadows are nearly non-existant except in the background. Texture is the real interest in this type of subject and much of that detail is lost due to overexposure.</td>', 'This is an interesting subject. The exposure could have been stopped down a bit. The highlights are blown out and the shadows are nearly non-existant except in the background. Texture is the real interest in this type of subject and much of that detail is lost due to overexposure.', '2006-07-03 14:14:54.000000', NULL, 1),
(2579215, 356235, 31399, '<td valign="top">very vivid colors ;-)</td>', 'very vivid colors ;-)', '2006-07-03 14:15:23.000000', NULL, 1),
