(2596611, 356360, 45194, '<td valign="top">Wow...breathtaking...the best shot I''ve seen so far having rated 27 photos in the contest.  I imagine you''re in the top 5 if not ribboning.  Great colors in the sky...nice silky water.  Great shot.</td>', 'Wow...breathtaking...the best shot I''ve seen so far having rated 27 photos in the contest.  I imagine you''re in the top 5 if not ribboning.  Great colors in the sky...nice silky water.  Great shot.', '2006-07-07 09:59:55.000000', NULL, 1),
(2596649, 357022, 60905, '<td valign="top">Gorgous, just beautiful, crop in from the right a bit and wow, still a ten in my eyes!</td>', 'Gorgous, just beautiful, crop in from the right a bit and wow, still a ten in my eyes!', '2006-07-07 10:11:23.000000', NULL, 1),
(2596653, 356492, 60905, '<td valign="top">Crop down from the top some, there seems to be to much up there and takes your eye right to that instead of subject, still very nicely done, cropping down also matches how much is in the reflection above the roof</td>', 'Crop down from the top some, there seems to be to much up there and takes your eye right to that instead of subject, still very nicely done, cropping down also matches how much is in the reflection above the roof', '2006-07-07 10:12:47.000000', NULL, 1),
(2596658, 356550, 60905, '<td valign="top">Focus could be better, the lighting stole it from the face a bit, legs and wings very focused, but eyes and head soft, the lighting very harsh on the plant.</td>', 'Focus could be better, the lighting stole it from the face a bit, legs and wings very focused, but eyes and head soft, the lighting very harsh on the plant.', '2006-07-07 10:14:00.000000', NULL, 1),
