(2597103, 356959, 38234, '<td valign="top">great shot of this beautiful rainbow</td>', 'great shot of this beautiful rainbow', '2006-07-07 11:55:50.000000', NULL, 1),
(2597104, 356895, 38234, '<td valign="top">great compositon and wonderful play of light and shadow</td>', 'great compositon and wonderful play of light and shadow', '2006-07-07 11:55:54.000000', NULL, 1),
(2597105, 357315, 38234, '<td valign="top">sweet shot with a great summer time feel to it</td>', 'sweet shot with a great summer time feel to it', '2006-07-07 11:55:57.000000', NULL, 1),
(2597106, 356443, 38234, '<td valign="top">love the DOF, detail and colour!!</td>', 'love the DOF, detail and colour!!', '2006-07-07 11:56:15.000000', NULL, 1),
(2597107, 356560, 38234, '<td valign="top">fantastic capture!!</td>', 'fantastic capture!!', '2006-07-07 11:56:21.000000', NULL, 1),
(2597259, 356162, 52500, '<td valign="top">This is a great capture, but the bird is a little too centered for my taste.  Still a very lovely photo.  7</td>', 'This is a great capture, but the bird is a little too centered for my taste.  Still a very lovely photo.  7', '2006-07-07 12:37:27.000000', NULL, 1),
(2597268, 357066, 208, '<td valign="top">He''s a bit too centered, I think. Maybe crop along the edge of the window?</td>', 'He''s a bit too centered, I think. Maybe crop along the edge of the window?', '2006-07-07 12:39:24.000000', NULL, 1),
(2597286, 357180, 52500, '<td valign="top">Focus is right on and super sharp, but the heavy shadow detracts from the overall image, IMO.  I realize the shadow forms a heart (and thus the Love part), but it doesn''t quite work for me.  Still, a good photo.  6</td>', 'Focus is right on and super sharp, but the heavy shadow detracts from the overall image, IMO.  I realize the shadow forms a heart (and thus the Love part), but it doesn''t quite work for me.  Still, a good photo.  6', '2006-07-07 12:42:50.000000', NULL, 1),
(2597294, 356939, 52500, '<td valign="top">Man, this is crazy!  I have no idea how you achieved this effect.  I like it!  IR maybe?</td>', 'Man, this is crazy!  I have no idea how you achieved this effect.  I like it!  IR maybe?', '2006-07-07 12:44:27.000000', NULL, 1),
(2597300, 356854, 52500, '<td valign="top">Now that is a crazy sculpture.  I like the point of view from which you chose to capture it.</td>', 'Now that is a crazy sculpture.  I like the point of view from which you chose to capture it.', '2006-07-07 12:45:32.000000', NULL, 1),
(2597310, 356798, 52500, '<td valign="top">Love the title.  I like the photo, but the lighting is a bit strange.  Perhaps a different time of day might have worked better.  Still, I like it and a 6 from me.</td>', 'Love the title.  I like the photo, but the lighting is a bit strange.  Perhaps a different time of day might have worked better.  Still, I like it and a 6 from me.', '2006-07-07 12:48:41.000000', NULL, 1),
(2597328, 356261, 52500, '<td valign="top">There is nothing more beautiful in nature than good ol'' fashioned bug sex.  Well done.</td>', 'There is nothing more beautiful in nature than good ol'' fashioned bug sex.  Well done.', '2006-07-07 13:00:10.000000', NULL, 1),
(2597333, 356368, 52500, '<td valign="top">Good idea and a good portrait in general, but the light is a bit too harsh IMO.</td>', 'Good idea and a good portrait in general, but the light is a bit too harsh IMO.', '2006-07-07 13:01:27.000000', NULL, 1),
(2597334, 356188, 52500, '<td valign="top">I think B/W was a good choice here, and I really like the use of negative space.</td>', 'I think B/W was a good choice here, and I really like the use of negative space.', '2006-07-07 13:02:05.000000', NULL, 1),
(2597336, 356308, 52500, '<td valign="top">Mmmm, ice cream.  Sorry, I don''t really have anything better to say.  I like it!</td>', 'Mmmm, ice cream.  Sorry, I don''t really have anything better to say.  I like it!', '2006-07-07 13:03:00.000000', NULL, 1),
(2597340, 356596, 52500, '<td valign="top">I just took my first pics of the ol'' bee on flower a couple of days ago, and it''s not easy to get a good composition without a crop with those guys bouncing around all over the place.  Well done!</td>', 'I just took my first pics of the ol'' bee on flower a couple of days ago, and it''s not easy to get a good composition without a crop with those guys bouncing around all over the place.  Well done!', '2006-07-07 13:04:34.000000', NULL, 1),
(2597350, 356525, 52500, '<td valign="top">Nice.  I''m sure you''re getting some flack for the blown out reflections on the water, but I like it like that.  Nice contrast to the almost completely unlit bird.</td>', 'Nice.  I''m sure you''re getting some flack for the blown out reflections on the water, but I like it like that.  Nice contrast to the almost completely unlit bird.', '2006-07-07 13:06:14.000000', NULL, 1),
