(2601788, 356958, 30982, '<td valign="top">In this challenge, I looked for good composition of a good subject.  While this has very good color and DOF, the composition is somewhat lacking (ie no "in context") and the subject isn''t particularly appealing to me.</td>', 'In this challenge, I looked for good composition of a good subject.  While this has very good color and DOF, the composition is somewhat lacking (ie no "in context") and the subject isn''t particularly appealing to me.', '2006-07-08 22:41:50.000000', NULL, 1),
(2601797, 356818, 30982, '<td valign="top">In this challenge, I looked for good composition/in-camera framing - in this picture, the OOF leaves in the foreground are a bit overwhelming for my taste, pulling the eye away from the rose.</td>', 'In this challenge, I looked for good composition/in-camera framing - in this picture, the OOF leaves in the foreground are a bit overwhelming for my taste, pulling the eye away from the rose.', '2006-07-08 22:43:40.000000', NULL, 1),
