INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2607798, 356206, 32997, '<td valign="top">quite simply the most interesting shot in this challenge..</td>', 'quite simply the most interesting shot in this challenge..', '2006-07-10 16:43:42.000000', NULL, 0),
(2607892, 356929, 22517, '<td valign="top">Hey Peter,<br/>Another outstanding Kinderdijk photo, very beautiful! Congratulations! I was considering coming to the Germany GTG but am not going to make it, would have loved to hear your talk and meet all the good people from DPC! Hopefully next time!</td>', 'Hey Peter,Another outstanding Kinderdijk photo, very beautiful! Congratulations! I was considering coming to the Germany GTG but am not going to make it, would have loved to hear your talk and meet all the good people from DPC! Hopefully next time!', '2006-07-10 17:12:08.000000', NULL, 0),
(2607925, 356611, 15711, '<td valign="top">He seems so thoughtful and kind.  Not hardly the king of "beasts," although that words doesn''t have to necessarily mean viscious.<br/> <br/>Just beautiful.</td>', 'He seems so thoughtful and kind.  Not hardly the king of "beasts," although that words doesn''t have to necessarily mean viscious. Just beautiful.', '2006-07-10 17:23:18.000000', NULL, 0),
(2608042, 357296, 45524, '<td valign="top">Greetings from the critique Club. Usually well done photos like this that score well dont need alot of help with critiqueing, This isnt an exception. Its a well done shot with pretty good techniques. Obviously some PP would help this shot, however not having that option with this challenge. You did very well out of the camera. A couple of quick suggestions I might add would have been to change the composition slightly so that the foreground wasnt so big. The horizon of the lake/mountain is almost dead center. You might also try to use a graduated ND filter and longer shutter. Other then that I cant suggest any improvements. Very well done shot and placement.</td>', 'Greetings from the critique Club. Usually well done photos like this that score well dont need alot of help with critiqueing, This isnt an exception. Its a well done shot with pretty good techniques. Obviously some PP would help this shot, however not having that option with this challenge. You did very well out of the camera. A couple of quick suggestions I might add would have been to change the composition slightly so that the foreground wasnt so big. The horizon of the lake/mountain is almost dead center. You might also try to use a graduated ND filter and longer shutter. Other then that I cant suggest any improvements. Very well done shot and placement.', '2006-07-10 18:05:30.000000', NULL, 0),
(2608058, 356626, 7889, '<td valign="top">Thanks for all your comments, much appreciated. Whilst I (naturally) like this shot I can see its not that ''pleasing'' to the majority of voters (some mean people gave it a 1  - shame on them!)<br/> <br/>Mike<br/></td>', 'Thanks for all your comments, much appreciated. Whilst I (naturally) like this shot I can see its not that ''pleasing'' to the majority of voters (some mean people gave it a 1  - shame on them!) Mike', '2006-07-10 18:12:31.000000', NULL, 0),
(2608090, 356929, 5728, '<td valign="top">Ya did good!</td>', 'Ya did good!', '2006-07-10 18:25:20.000000', NULL, 0),
(2608188, 357066, 41746, '<td valign="top">I was hoping this strong image would make it into top ten. So close, Ragga, and only a question of time when you ribbon. One of my favorites in the challenge. Congrats!</td>', 'I was hoping this strong image would make it into top ten. So close, Ragga, and only a question of time when you ribbon. One of my favorites in the challenge. Congrats!', '2006-07-10 18:42:27.000000', NULL, 0),
(2608211, 355962, 39850, '<td valign="top">Was fairly confident this was yours.  Again, very good moment/character capture.  <i>Temporary Note</i> If you get ''bored'' <i>(and the quality size-wise is there)</i> a crop/framing of ''Donald'' be amusing... <i>(still keen to see Lesotho Man triptych too)</i>.</td>', 'Was fairly confident this was yours.  Again, very good moment/character capture.  Temporary Note If you get ''bored'' (and the quality size-wise is there) a crop/framing of ''Donald'' be amusing... (still keen to see Lesotho Man triptych too).', '2006-07-10 18:46:45.000000', NULL, 0),
(2608231, 357063, 39850, '<td valign="top">Was confident this was yours, glad I was right.  Straight from the camera - framed like this, with the character of the ''fore'' and the background subjects - very good, again, as usual.</td>', 'Was confident this was yours, glad I was right.  Straight from the camera - framed like this, with the character of the ''fore'' and the background subjects - very good, again, as usual.', '2006-07-10 18:52:15.000000', NULL, 0),
(2608277, 357228, 30982, '<td valign="top">Trading Post comment<br/> <br/>Pretty good score for cotton swabs, but then again, Tim ribboned with ''em, so go figure!<br/> <br/>It came out pretty sharp and I''d say the colors are pretty good, except I''d have gone with a different background color - it does seem a bit bland of a color.  Very good in-camera framing with good lines/balance.</td>', 'Trading Post comment Pretty good score for cotton swabs, but then again, Tim ribboned with ''em, so go figure! It came out pretty sharp and I''d say the colors are pretty good, except I''d have gone with a different background color - it does seem a bit bland of a color.  Very good in-camera framing with good lines/balance.', '2006-07-10 19:03:34.000000', NULL, 0),
(2608309, 356098, 30982, '<td valign="top">Trading Post comment<br/> <br/>I''m wondering if you turned up the "contrast" or "sharpness" on the 20D''s picture style for this challenge.  Colors are pretty good (Canon''s quite good on that count) but it does indeed need a bit of sharpening.  And yes, I know it''s "out of the camera".  :-)<br/> <br/>Composition - would like to see the whole boat in frame, or at least enough of the back to know we had all the people in the frame.  Love the title, by the way.</td>', 'Trading Post comment I''m wondering if you turned up the "contrast" or "sharpness" on the 20D''s picture style for this challenge.  Colors are pretty good (Canon''s quite good on that count) but it does indeed need a bit of sharpening.  And yes, I know it''s "out of the camera".  :-) Composition - would like to see the whole boat in frame, or at least enough of the back to know we had all the people in the frame.  Love the title, by the way.', '2006-07-10 19:11:47.000000', NULL, 0),
(2608366, 356515, 30982, '<td valign="top">Trading Post comment<br/> <br/>Interesting juxtaposition of shapes and nice "illusion" created regarding the bottles (I''m assuming they''re all really the same size).  Simple, effective composition, and excellent lighting, as usual.  Your studio work is always very well done.  Oh, and very nice glass, too. :-)</td>', 'Trading Post comment Interesting juxtaposition of shapes and nice "illusion" created regarding the bottles (I''m assuming they''re all really the same size).  Simple, effective composition, and excellent lighting, as usual.  Your studio work is always very well done.  Oh, and very nice glass, too. :-)', '2006-07-10 19:26:40.000000', NULL, 0),
